fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    let n = v.len();
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        matrix.push(create_row(&v, i));
    }
    matrix
}

fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    let n = v.len();
    // start with a row of all zeros
    let mut row = vec![0.0; n];
    // put the i-th element of v on the diagonal
    row[i] = v[i];
    row
}

